import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CANn83f8.js";const p=JSON.parse('{"title":"Create your account","description":"Register for ExpenseAutomator and verify your email address.","frontmatter":{"title":"Create your account","description":"Register for ExpenseAutomator and verify your email address.","aside":false,"prev":{"text":"Getting started","link":"/getting-started/"},"next":{"text":"Complete account setup","link":"/getting-started/account-setup"}},"headers":[],"relativePath":"getting-started/create-account.md","filePath":"getting-started/create-account.md","lastUpdated":1790713879000}'),i={name:"getting-started/create-account.md"};function s(n,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div class="doc-eyebrow">Getting started</div><h1 id="create-your-account" tabindex="-1">Create your account <a class="header-anchor" href="#create-your-account" aria-label="Permalink to &quot;Create your account&quot;">​</a></h1><p>Choose how you want to register, confirm your account details, and verify your email before beginning the guided setup.</p><h2 id="before-you-register" tabindex="-1">Before you register <a class="header-anchor" href="#before-you-register" aria-label="Permalink to &quot;Before you register&quot;">​</a></h2><p>ExpenseAutomator offers a free plan and Premium options. The registration page shows the selected plan, its price, and whether a trial applies before you submit any details.</p><div class="doc-callout"><p>A payment card is not required to create the free account or begin the Premium trial. Always review the current plan details shown on the registration page.</p></div><h2 id="register-with-email" tabindex="-1">Register with email <a class="header-anchor" href="#register-with-email" aria-label="Permalink to &quot;Register with email&quot;">​</a></h2><div class="steps"><div class="step"><h3>Open the pricing page</h3><p>Go to <a href="https://expenseautomator.com/pricing">https://expenseautomator.com/pricing</a> and select a plan.</p></div><div class="step"><h3>Enter your account details</h3><p>Provide your email address, create a password of at least eight characters, and enter the password again for confirmation.</p></div><div class="step"><h3>Complete the security check</h3><p>Complete the reCAPTCHA challenge, then submit the registration form.</p></div><div class="step"><h3>Verify your email</h3><p>Open the verification message sent to your inbox and follow its activation link. Expired or previously used links cannot activate an account.</p></div><div class="step"><h3>Premium Plan Checkout</h3><p>If you choose one of the Premium Monthly or Annual plans, you will be redirected to the Stripe payment flow.</p></div></div><h2 id="register-with-google" tabindex="-1">Register with Google <a class="header-anchor" href="#register-with-google" aria-label="Permalink to &quot;Register with Google&quot;">​</a></h2><p>Select <strong>Sign up with Google</strong> on the registration page and complete Google&#39;s authorisation flow. ExpenseAutomator preserves the plan selected before you leave the page.</p><h2 id="if-the-verification-message-does-not-arrive" tabindex="-1">If the verification message does not arrive <a class="header-anchor" href="#if-the-verification-message-does-not-arrive" aria-label="Permalink to &quot;If the verification message does not arrive&quot;">​</a></h2><p>Check the spam or junk folder and confirm that the address entered during registration is correct. Avoid creating several accounts in quick succession; instead, return to sign in and follow the available account recovery guidance.</p>',12)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
